if(PHP_SAPI!=='cli'){fwrite(STDERR,"ERROR: CLI only.\n");exit(1);}
$options=getopt('',array('source:','wp-load:','user-id:','company-id::','apply','help'));
if(isset($options['help'])){echo "Imports flat_rate_cat, flat_rate_table, flatrateconfig, prevprices and pagreement.\nDry run is the default; add --apply after review.\n";exit(0);}
$source=(string)($options['source']??'');$wp_load=(string)($options['wp-load']??'');$user_id=(int)($options['user-id']??0);$company_id=(int)($options['company-id']??1);$apply=isset($options['apply']);
if(!$source||!is_readable($source)){fwrite(STDERR,"ERROR: --source must identify a readable legacy SQL dump.\n");exit(1);}
if(!$wp_load||!is_file($wp_load)||$user_id<1||$company_id<1){fwrite(STDERR,"ERROR: valid --wp-load, --user-id and --company-id are required.\n");exit(1);}
require_once $wp_load;wp_set_current_user($user_id);
if(!defined('SERVSYS_DB_VERSION')||SERVSYS_DB_VERSION<15){fwrite(STDERR,"ERROR: ServSys DB version 15 or newer is required.\n");exit(1);}
if(!\ServSys\Users\Authorization::is_wordpress_admin($user_id)){fwrite(STDERR,"ERROR: --user-id must be a WordPress Administrator.\n");exit(1);}
if(\ServSys\Companies\CompanyContext::current_company_id()!==$company_id){if(!$apply){fwrite(STDERR,"ERROR: dry run will not change company context; select company {$company_id} first.\n");exit(1);}\ServSys\Companies\CompanyContext::set_current_company_id($company_id);}
if(\ServSys\Companies\CompanyContext::current_company_id()!==$company_id){fwrite(STDERR,"ERROR: unable to select company.\n");exit(1);}

function servsys_p9_sql_unescape(string $v): string{return strtr($v,array("\\0"=>"\0","\\n"=>"\n","\\r"=>"\r","\\Z"=>"\x1a","\\'"=>"'",'\\"'=>'"', "\\\\"=>"\\"));}
function servsys_p9_tuple(string $tuple): array {$out=array();$v='';$q=false;$e=false;for($i=0,$n=strlen($tuple);$i<$n;$i++){$ch=$tuple[$i];if($q){if($e){$v.='\\'.$ch;$e=false;}elseif('\\'===$ch){$e=true;}elseif("'"===$ch){$q=false;}else{$v.=$ch;}}elseif("'"===$ch){$q=true;}elseif(','===$ch){$t=trim($v);$out[]='NULL'===strtoupper($t)?null:servsys_p9_sql_unescape($t);$v='';}else{$v.=$ch;}}$t=trim($v);$out[]='NULL'===strtoupper($t)?null:servsys_p9_sql_unescape($t);return $out;}
function servsys_p9_rows(string $sql,string $table): array {$needle='INSERT INTO `'.$table.'` VALUES';$rows=array();$offset=0;while(false!==($start=strpos($sql,$needle,$offset))){$semi=strpos($sql,';',$start);if(false===$semi){throw new RuntimeException("Unterminated INSERT for {$table}.");}$buf=substr($sql,$start+strlen($needle),$semi-$start-strlen($needle));$tuple='';$depth=0;$q=false;$e=false;for($i=0,$n=strlen($buf);$i<$n;$i++){$ch=$buf[$i];if($q){if($e){$e=false;}elseif('\\'===$ch){$e=true;}elseif("'"===$ch){$q=false;}if($depth>0){$tuple.=$ch;}continue;}if("'"===$ch){$q=true;if($depth>0){$tuple.=$ch;}}elseif('('===$ch){if(0===$depth){$tuple='';}else{$tuple.=$ch;}$depth++;}elseif(')'===$ch){$depth--;if(0===$depth){$rows[]=servsys_p9_tuple($tuple);}elseif($depth>0){$tuple.=$ch;}}elseif($depth>0){$tuple.=$ch;}}$offset=$semi+1;}return $rows;}
function servsys_p9_text($v): string {$v=trim((string)$v);return in_array(strtolower($v),array('null','-'),true)?'':$v;}
function servsys_p9_date($v): ?string {$v=trim((string)$v);if(''===$v||'0000-00-00'===$v||'2000-01-01'===$v){return null;}$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);return $d&&$d->format('Y-m-d')===$v?$v:null;}
function servsys_p9_period($v): ?array {$v=trim((string)$v);if(''===$v||'null'===strtolower($v)){return null;}if(preg_match('/^(0?[1-9]|1[0-2])[\\/\\-](\\d{4})$/',$v,$m)){return array((int)$m[2],(int)$m[1],null);}if(preg_match('/^(\\d{4})[\\/\\-](0?[1-9]|1[0-2])$/',$v,$m)){return array((int)$m[1],(int)$m[2],null);}$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);if($d&&$d->format('Y-m-d')===$v){return array((int)$d->format('Y'),(int)$d->format('m'),$v);}return null;}

$sql=file_get_contents($source);$tables=array();foreach(array('flat_rate_cat','flat_rate_table','flatrateconfig','prevprices','pagreement') as $t){$tables[$t]=servsys_p9_rows($sql,$t);}
$ignored=array('flat_rate','flat_rate_date','prevprices_date','servsync');
global $wpdb;$now=current_time('mysql',true);
$T=function($name)use($wpdb){return $wpdb->prefix.$name;};
$summary=array('flat_categories'=>count($tables['flat_rate_cat']),'flat_items'=>count($tables['flat_rate_table']),'flat_config_rows'=>count($tables['flatrateconfig']),'pm_plans'=>count($tables['prevprices']),'pm_agreements'=>count($tables['pagreement']),'unmapped_customers'=>0,'unmapped_sites'=>0,'unmapped_equipment'=>0,'unparsed_visits'=>0,'flat_inventory_links'=>0,'flat_manual_materials'=>0,'existing_flat_items'=>0,'existing_pm_plans'=>0,'existing_pm_agreements'=>0);
$customers=array();foreach($wpdb->get_results($wpdb->prepare('SELECT id,legacy_custnum FROM %i WHERE company_id=%d',$T('servsys_customers'),$company_id),ARRAY_A) as $r){if(null!==$r['legacy_custnum']){$customers[(string)$r['legacy_custnum']]=(int)$r['id'];}}
$sites=array();foreach($wpdb->get_results($wpdb->prepare('SELECT id,customer_id,legacy_custsite,legacy_sitenum FROM %i WHERE company_id=%d',$T('servsys_sites'),$company_id),ARRAY_A) as $r){$sites[(int)$r['customer_id'].'|'.trim((string)$r['legacy_custsite']).'|'.trim((string)$r['legacy_sitenum'])]=(int)$r['id'];}
$equipment=array();foreach($wpdb->get_results($wpdb->prepare('SELECT id,customer_id,site_id,legacy_enum FROM %i WHERE company_id=%d',$T('servsys_equipment'),$company_id),ARRAY_A) as $r){if(null!==$r['legacy_enum']){$equipment[(string)$r['legacy_enum']]=$r;}}
$inventory=array();foreach($wpdb->get_results($wpdb->prepare('SELECT id,sku FROM %i WHERE company_id=%d',$T('servsys_inventory_items'),$company_id),ARRAY_A) as $r){$inventory[strtoupper(trim($r['sku']))]=(int)$r['id'];}
$category_ids=array();foreach($wpdb->get_results($wpdb->prepare('SELECT id,name FROM %i WHERE company_id=%d',$T('servsys_flat_rate_categories'),$company_id),ARRAY_A) as $r){$category_ids[strtolower(trim($r['name']))]=(int)$r['id'];}

foreach($tables['flat_rate_table'] as $r){if(count($r)!==9){throw new RuntimeException('Unexpected flat_rate_table column count.');}$existing=$wpdb->get_var($wpdb->prepare('SELECT id FROM %i WHERE company_id=%d AND code=%d',$T('servsys_flat_rate_items'),$company_id,(int)$r[0]));if($existing){$summary['existing_flat_items']++;}$key=strtoupper(servsys_p9_text($r[3]));if($key&&isset($inventory[$key])){$summary['flat_inventory_links']++;}elseif((float)$r[5]>0){$summary['flat_manual_materials']++;}}
foreach($tables['prevprices'] as $r){$existing=$wpdb->get_var($wpdb->prepare('SELECT id FROM %i WHERE legacy_planrec=%d',( $T('servsys_pm_plans') ),(int)$r[0]));if($existing){$summary['existing_pm_plans']++;}}
foreach($tables['pagreement'] as $r){if(count($r)!==29){throw new RuntimeException('Unexpected pagreement column count.');}$cust=$customers[(string)$r[1]]??0;if(!$cust){$summary['unmapped_customers']++;continue;}$site=$sites[$cust.'|'.trim((string)$r[26]).'|'.trim((string)$r[27])]??0;if(!$site){$summary['unmapped_sites']++;}$existing=$wpdb->get_var($wpdb->prepare('SELECT id FROM %i WHERE legacy_contnum=%d',$T('servsys_pm_agreements'),(int)$r[0]));if($existing){$summary['existing_pm_agreements']++;}foreach(array_slice($r,2,10) as $enum){if((int)$enum&&!isset($equipment[(string)(int)$enum])){$summary['unmapped_equipment']++;}}foreach(array_slice($r,19,6) as $visit){if(servsys_p9_text($visit)&&!servsys_p9_period($visit)){$summary['unparsed_visits']++;}}}
echo "ServSys legacy Flat Rate / PM migration\nMode: ".($apply?'APPLY':'DRY RUN - NO CHANGES')."\nSource: {$source}\nCompany: {$company_id}\nIgnored legacy sync/reconciliation sources: ".implode(', ',$ignored)."\n\n";foreach($summary as $k=>$v){echo str_pad($k,28).": {$v}\n";}
if(!$apply){echo "\nNo database changes were made. Resolve all unmapped/unparsed counts before --apply.\n";exit(($summary['unmapped_customers']||$summary['unmapped_sites']||$summary['unmapped_equipment']||$summary['unparsed_visits'])?2:0);}
if($summary['unmapped_customers']||$summary['unmapped_sites']||$summary['unmapped_equipment']||$summary['unparsed_visits']){fwrite(STDERR,"ERROR: apply refused because migration mappings are incomplete.\n");exit(2);}

/* phpcs:disable WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching -- One-time audited migration utility. */
$wpdb->query('START TRANSACTION');
try{
 foreach($tables['flat_rate_cat'] as $r){$name=servsys_p9_text($r[1]);if(!$name)continue;$key=strtolower($name);if(!isset($category_ids[$key])){$wpdb->insert($T('servsys_flat_rate_categories'),array('company_id'=>$company_id,'name'=>$name,'sort_order'=>(int)$r[0],'active'=>1,'created_at'=>$now,'updated_at'=>$now,'created_by'=>$user_id,'updated_by'=>$user_id));$category_ids[$key]=(int)$wpdb->insert_id;}}
 if($tables['flatrateconfig']){$r=$tables['flatrateconfig'][0];$data=array('labor_rate'=>(float)$r[0],'agreement_repair_multiplier'=>(float)$r[1],'additional_repair_multiplier'=>(float)$r[2],'commercial_multiplier'=>(float)$r[3],'sales_tax_percent'=>(float)$r[4],'part_markup_multiplier'=>(float)$r[5],'special_item_low_price'=>(float)$r[6],'special_item_high_price'=>(float)$r[7],'special_item_high_hours'=>(float)$r[8],'updated_at'=>$now,'updated_by'=>$user_id);$id=$wpdb->get_var($wpdb->prepare('SELECT id FROM %i WHERE company_id=%d',$T('servsys_flat_rate_config'),$company_id));if($id){$wpdb->update($T('servsys_flat_rate_config'),$data,array('id'=>$id,'company_id'=>$company_id));}else{$data['company_id']=$company_id;$data['created_at']=$now;$data['created_by']=$user_id;$wpdb->insert($T('servsys_flat_rate_config'),$data);}}
 foreach($tables['flat_rate_table'] as $r){$code=(int)$r[0];$id=$wpdb->get_var($wpdb->prepare('SELECT id FROM %i WHERE company_id=%d AND code=%d',$T('servsys_flat_rate_items'),$company_id,$code));if($id)continue;$cat=$category_ids[strtolower(servsys_p9_text($r[2]))]??null;$wpdb->insert($T('servsys_flat_rate_items'),array('company_id'=>$company_id,'category_id'=>$cat,'code'=>$code,'description'=>servsys_p9_text($r[1])?:('Legacy Flat Rate '.$code),'customer_notes'=>servsys_p9_text($r[6]),'labor_hours'=>max(0,(float)$r[4]),'no_discount'=>(int)('1'===trim((string)$r[7])),'special_item'=>(int)((int)$r[8]!==0),'active'=>1,'created_at'=>$now,'updated_at'=>$now,'created_by'=>$user_id,'updated_by'=>$user_id));$id=(int)$wpdb->insert_id;$key=strtoupper(servsys_p9_text($r[3]));$cost=max(0,(float)$r[5]);if($key&&isset($inventory[$key])){$wpdb->insert($T('servsys_flat_rate_item_materials'),array('company_id'=>$company_id,'flat_rate_item_id'=>$id,'inventory_item_id'=>$inventory[$key],'quantity'=>1,'sort_order'=>0,'created_at'=>$now,'updated_at'=>$now,'created_by'=>$user_id,'updated_by'=>$user_id));}elseif($cost>0){$wpdb->insert($T('servsys_flat_rate_item_materials'),array('company_id'=>$company_id,'flat_rate_item_id'=>$id,'quantity'=>1,'manual_description'=>$key?:'Legacy material cost','manual_unit_cost'=>$cost,'sort_order'=>0,'created_at'=>$now,'updated_at'=>$now,'created_by'=>$user_id,'updated_by'=>$user_id));}}
 foreach($tables['prevprices'] as $r){$planrec=(int)$r[0];$id=$wpdb->get_var($wpdb->prepare('SELECT id FROM %i WHERE legacy_planrec=%d',$T('servsys_pm_plans'),$planrec));if($id)continue;$wpdb->insert($T('servsys_pm_plans'),array('company_id'=>$company_id,'legacy_planrec'=>$planrec,'description'=>servsys_p9_text($r[1])?:('Legacy PM Plan '.$planrec),'tm_estimate'=>max(0,(float)$r[2]),'active'=>1,'created_at'=>$now,'updated_at'=>$now,'created_by'=>$user_id,'updated_by'=>$user_id));$id=(int)$wpdb->insert_id;foreach(array(12=>$r[3],24=>$r[4],36=>$r[5]) as $months=>$price){if(null!==$price&&''!==trim((string)$price)){$wpdb->insert($T('servsys_pm_plan_terms'),array('company_id'=>$company_id,'pm_plan_id'=>$id,'term_months'=>$months,'price'=>max(0,(float)$price),'sort_order'=>$months,'created_at'=>$now,'updated_at'=>$now,'created_by'=>$user_id,'updated_by'=>$user_id));}}}
 foreach($tables['pagreement'] as $r){$cont=(int)$r[0];if($wpdb->get_var($wpdb->prepare('SELECT id FROM %i WHERE legacy_contnum=%d',$T('servsys_pm_agreements'),$cont)))continue;$cust=$customers[(string)$r[1]];$site=$sites[$cust.'|'.trim((string)$r[26]).'|'.trim((string)$r[27])];$start=servsys_p9_date($r[13])?:'2000-01-01';$end=servsys_p9_date($r[14])?:$start;$term_raw=max(0,(int)$r[15]);$term_months=$term_raw>0?$term_raw*12:max(1,(int)round((strtotime($end)-strtotime($start))/2629800));$wpdb->insert($T('servsys_pm_agreements'),array('company_id'=>$company_id,'customer_id'=>$cust,'site_id'=>$site,'pm_plan_id'=>null,'legacy_contnum'=>$cont,'agreement_date'=>servsys_p9_date($r[18]),'start_date'=>$start,'end_date'=>$end,'term_months'=>$term_months,'contract_price'=>max(0,(float)$r[16]),'plan_description_snapshot'=>'Legacy Preventive Maintenance Agreement','plan_tm_estimate_snapshot'=>0,'visits_per_year'=>max(0,(int)$r[19-1]),'additional_services'=>servsys_p9_text($r[12]),'notes'=>servsys_p9_text($r[17]),'status'=>strtotime($end)<time()?'expired':'active','created_at'=>$now,'updated_at'=>$now,'created_by'=>$user_id,'updated_by'=>$user_id));$aid=(int)$wpdb->insert_id;foreach(array_slice($r,2,10) as $enum){$enum=(int)$enum;if(!$enum)continue;$eq=$equipment[(string)$enum];if((int)$eq['customer_id']!==$cust||(int)$eq['site_id']!==$site){throw new RuntimeException("Agreement {$cont} equipment {$enum} does not belong to mapped site.");}$wpdb->insert($T('servsys_pm_agreement_equipment'),array('company_id'=>$company_id,'pm_agreement_id'=>$aid,'equipment_id'=>(int)$eq['id'],'created_at'=>$now,'created_by'=>$user_id));}foreach(array_slice($r,19,6) as $visit){$period=servsys_p9_period($visit);if(!$period)continue;$wpdb->insert($T('servsys_pm_scheduled_visits'),array('company_id'=>$company_id,'pm_agreement_id'=>$aid,'scheduled_year'=>$period[0],'scheduled_month'=>$period[1],'scheduled_date'=>$period[2],'status'=>'scheduled','notes'=>'Imported from legacy PM agreement.','created_at'=>$now,'updated_at'=>$now,'created_by'=>$user_id,'updated_by'=>$user_id));}}
